using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;using XHLLauncher;
class DesktopChecks {
 static int count;static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);count++;}
 static void Main(string[] args){try{Run(args);}catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}}
 static void Run(string[] args){string root=Path.Combine(args[0],"desktop-fixture-"+Guid.NewGuid().ToString("N")),server=Path.Combine(root,"server"),app=Path.Combine(root,"app");Directory.CreateDirectory(Path.Combine(server,"savegame"));Directory.CreateDirectory(Path.Combine(server,"logs"));Directory.CreateDirectory(app);string cfg="{\"name\":\"Fixture\",\"saveDirectory\":\"savegame\",\"logDirectory\":\"logs\",\"slotCount\":16,\"queryPort\":15637,\"gameSettingsPreset\":\"Custom\",\"gameSettings\":{\"enemyDamageFactor\":0.6},\"userGroups\":[{\"name\":\"Admin\",\"password\":\"secret fixture password\",\"canKickBan\":true}]}";File.WriteAllText(Path.Combine(server,"enshrouded_server.json"),cfg);File.WriteAllText(Path.Combine(server,"savegame","world.ksd"),"world sentinel");File.WriteAllText(Path.Combine(server,"XHL-PLAYER-SESSIONS.csv"),"Player,Joined,Left,Duration\nFixture Visitor,2026-10-18 10:00:00,2026-10-18 10:10:00,600\n");string hash=InstallationAudit.Hash(Path.Combine(server,"savegame","world.ksd"));
  Check(DesktopWindow.TrustedSource("https://shroudforge.local/index.html"),"Local packaged interface can use the desktop bridge");foreach(string origin in new[]{"https://shroudforge.local.evil/index.html","https://enshroudeddatabase.com/map/","http://shroudforge.local/index.html","file:///index.html","https://shroudforge.local/other.html"})Check(!DesktopWindow.TrustedSource(origin),"Untrusted origin rejected: "+origin);
  var settings=new LauncherSettings{ServerRoot=server,ServerName="Fixture",PhoneViewEnabled=false,PublicIpLookup=false,PhoneViewKey="private-fixture-key",AutoBackup=false,AutoRestartOnCrash=false};using(var engine=new DesktopEngine(app,settings,true)){engine.Start().GetAwaiter().GetResult();foreach(string op in new[]{"Start","Stop","Restart","SaveField","Restore","ModStartup","Recovery","AutoBackup","Backup","RemoveMod"}){var result=engine.Command(op,new Dictionary<string,object>()).GetAwaiter().GetResult();Check(!result.Success&&result.Message.StartsWith("Read-only preview"),"Preview denies "+op+" before any game or config action");}string json=new JavaScriptSerializer().Serialize(engine.Snapshot());Check(!json.Contains("secret fixture password")&&!json.Contains("private-fixture-key"),"Desktop state excludes group passwords and phone access keys");Check(json.Contains("Fixture Visitor")&&json.Contains("RECORDED VISITS"),"Completed-session identities and full observed profiles reach modern UI");Check(json.Contains("CURRENT SESSION   Unavailable")||json.Contains("CURRENT SESSION   Not available"),"Offline profiles do not invent a running session");Check(json.Contains("memoryHistory")&&json.Contains("cpuHistory"),"Both measured history series reach the dashboard");File.WriteAllText(Path.Combine(args[0],"snapshot.json"),json);Check(json.Contains("Join group not exposed")||json.Contains("individualRoles"),"Moderation capabilities are explicit rather than invented");}
  Check(File.ReadAllText(Path.Combine(server,"enshrouded_server.json"))==cfg&&InstallationAudit.Hash(Path.Combine(server,"savegame","world.ksd"))==hash,"Preview leaves configuration and world bytes unchanged");
  string log=Path.Combine(root,"private.log");File.WriteAllText(log,"{\"password\":\"secret with spaces\"}\nPhoneViewKey=abcdef\nhttp://127.0.0.1:8765/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/status");string tail=IncidentEvidence.Tail(log,4096);Check(!tail.Contains("secret with spaces")&&!tail.Contains("abcdef")&&!tail.Contains("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"),"Evidence redacts quoted credentials and private phone URL paths");Console.WriteLine(count+" desktop safety checks passed.");
 }
}
